import { useEffect } from "react";
import { syncThemePreference, useAccountStore } from "../lib/auth";
import { useThemeStore } from "../store/theme";

export function ThemeController() {
  const session = useAccountStore((state) => state.session);
  const setUserTheme = useAccountStore((state) => state.setUserTheme);
  const themeId = useThemeStore((state) => state.themeId);
  const pendingSync = useThemeStore((state) => state.pendingSync);
  const applyRemoteTheme = useThemeStore((state) => state.applyRemoteTheme);
  const markSynced = useThemeStore((state) => state.markSynced);
  const syncFromStorage = useThemeStore((state) => state.syncFromStorage);

  useEffect(() => {
    const onStorage = (event: StorageEvent) => {
      if (
        event.key === "inkflow:theme:v2" ||
        event.key === "inkflow:theme-pending-sync:v1"
      ) {
        syncFromStorage();
      }
    };
    window.addEventListener("storage", onStorage);
    return () => window.removeEventListener("storage", onStorage);
  }, [syncFromStorage]);

  useEffect(() => {
    if (!session) return;
    // 本机账号没有远端可同步，皮肤就用手上这套。
    if (session.local) return;
    const remoteTheme = session.user.themeId ?? "moon";

    if (pendingSync) {
      void syncThemePreference(session.accessToken, themeId)
        .then(({ user }) => {
          setUserTheme(user.themeId);
          markSynced();
        })
        .catch(() => {
          // Keep the pending flag. The next sign-in or launch retries it.
        });
      return;
    }

    if (remoteTheme !== themeId) applyRemoteTheme(remoteTheme);
  }, [
    applyRemoteTheme,
    markSynced,
    pendingSync,
    session,
    setUserTheme,
    themeId,
  ]);

  return null;
}
