function WordDrawer({
  onClose,
  onOpenGallery,
}: {
  onClose: () => void;
  /** 打开 leafia://wordbook 那扇浏览器窗口：背过的词铺成一片卡片场。 */
  onOpenGallery: () => void;
}) {
  const navigate = useNavigate();
  const initialized = useVocabulary((state) => state.initialized);
  const hydrate = useVocabulary((state) => state.hydrate);
  const words = useVocabulary((state) => state.words);
  const startReviewWithIds = useVocabulary(
    (state) => state.startReviewWithIds,
  );
  const storedPlan = useMemo(loadWordStudyPlan, []);
  const dueCount = words.filter(
    (word) => new Date(word.nextReviewAt).getTime() <= Date.now(),
  ).length;
  const [categoryId, setCategoryId] = useState<string>("all");
  const [dailyLimit, setDailyLimit] = useState(
    storedPlan?.dailyNewLimit ?? 20,
  );
  const [selectedIds, setSelectedIds] = useState<string[]>(
    storedPlan?.wordIds ?? words.slice(0, 20).map((word) => word.id),
  );
  const [notice, setNotice] = useState<string | null>(null);

  useEffect(() => {
    void hydrate();
  }, [hydrate]);

  const visibleWords = words.filter(
    (word) => categoryId === "all" || word.categoryId === categoryId,
  );
  const selected = new Set(selectedIds);
  const mastered = words.filter((word) => word.mastery === "mastered").length;

  const start = () => {
    if (selectedIds.length === 0) {
      setNotice("请先选择至少一个单词。");
      return;
    }
    const plan = createWordStudyPlan(selectedIds, dailyLimit);
    saveWordStudyPlan(plan);
    const queue = buildDailyWordQueue(words, plan);
    startReviewWithIds(queue.length ? queue : selectedIds);
    onClose();
    navigate("/vocabulary");
  };

  return (
    <>
      <div className="leafia-drawer-stats">
        <span>
          <strong>{dueCount}</strong>
          今日到期
        </span>
        <span>
          <strong>{selectedIds.length}</strong>
          已选单词
        </span>
        <span>
          <strong>{mastered}</strong>
          已掌握
        </span>
      </div>

      {/* 抽屉里挑词之后，抬头就能换一种翻法：这扇窗把背过的卡片铺成一片
          会往前漂的场子（浏览器窗口的样子）。 */}
      <button
        type="button"
        className="leafia-drawer-gallery"
        onClick={() => {
          onOpenGallery();
          onClose();
        }}
      >
        <GalleryHorizontalEnd size={15} />
        在卡片场里翻一遍
        <small>leafia://wordbook</small>
      </button>

      <section className="leafia-drawer-section">
        <header>
          <div>
            <span className="knowledge-eyebrow">Daily plan</span>
            <h4>每日新词</h4>
          </div>
          <strong>{dailyLimit}</strong>
        </header>
        <div className="leafia-drawer-segments">
          {[10, 20, 30, 50].map((value) => (
            <button
              type="button"
              key={value}
              className={cn(dailyLimit === value && "is-active")}
              onClick={() => setDailyLimit(value)}
            >
              {value}
            </button>
          ))}
          <label>
            <input
              type="number"
              min={1}
              max={200}
              value={dailyLimit}
              onChange={(event) =>
                setDailyLimit(
                  Math.max(1, Math.min(200, Number(event.target.value) || 1)),
                )
              }
              aria-label="自定义每日新词数"
            />
          </label>
        </div>
        <p className="leafia-drawer-note">
          到期复习词优先。每个单词完成一次词义识别和一次拼写，答错会回到队尾。
        </p>
      </section>

      <section className="leafia-drawer-section">
        <header>
          <div>
            <span className="knowledge-eyebrow">Word source</span>
            <h4>选择背诵范围</h4>
          </div>
          <button
            type="button"
            onClick={() => setSelectedIds(visibleWords.map((word) => word.id))}
          >
            全选
          </button>
        </header>
        <div className="leafia-drawer-segments">
          <button
            type="button"
            className={cn(categoryId === "all" && "is-active")}
            onClick={() => setCategoryId("all")}
          >
            全部
          </button>
          {KNOWLEDGE_CATEGORIES.map((category) => (
            <button
              type="button"
              key={category.id}
              className={cn(categoryId === category.id && "is-active")}
              onClick={() => setCategoryId(category.id)}
            >
              {category.titleZh}
            </button>
          ))}
        </div>
      </section>

      <section className="leafia-word-picker">
        {visibleWords.slice(0, 80).map((word) => {
          const checked = selected.has(word.id);
          return (
            <article
              key={word.id}
              className={cn("leafia-word-flip", checked && "is-selected")}
            >
              <FlipCard
                width={240}
                height={150}
                radius={10}
                background="#fffdf9"
                color="#28302c"
                shadow={false}
                tilt={false}
                ariaLabel={`${word.term} word card`}
                front={
                  <div className="leafia-word-flip__face">
                    <small>{word.partOfSpeech ?? "expression"}</small>
                    <strong>{word.term}</strong>
                    <span>{word.pronunciation ?? "IPA pending"}</span>
                  </div>
                }
                back={
                  <div className="leafia-word-flip__face is-back">
                    <small>Meaning</small>
                    <strong>{word.meaningsZh.join("；")}</strong>
                    <span>{word.definitionEn}</span>
                  </div>
                }
              />
              <button
                type="button"
                className={cn(checked && "is-selected")}
                onClick={() =>
                  setSelectedIds((current) =>
                    current.includes(word.id)
                      ? current.filter((id) => id !== word.id)
                      : [...current, word.id],
                  )
                }
              >
                {checked ? <Check size={13} /> : null}
                {checked ? "已选" : "选入复习"}
              </button>
            </article>
          );
        })}
      </section>

      {notice ? <p className="leafia-drawer-notice">{notice}</p> : null}
      <button
        type="button"
        className="knowledge-primary-button"
        onClick={start}
        disabled={!initialized && words.length === 0}
      >
        <BookOpen size={15} />
        开始两遍复习
      </button>
    </>
  );
}

/** 要点和关联词汇两个字段都是「一行一条，逗号也认」。 */
function splitCardLines(value: string) {
  return value
    .split(/\n|,/)
    .map((item) => item.trim())
    .filter(Boolean);
}

/**
 * 知识卡的正反面（D1）。
 * 正面是一眼就能读完的那一层，背面是要点、关联词汇和出处 —— 卡片翻过去才看细节，
 * 列表里翻着看，写入界面里那张预览也是同一副面孔，写的时候就知道它长什么样。
 */
function knowledgeCardFaces({
  categoryLabel,
  sourceLabel,
  title,
  summary,
  bookTitle,
  keyPoints,
  terms,
  quote,
  mastered,
  placeholder,
}: {
  categoryLabel: string;
  sourceLabel: string;
  title: string;
  summary: string;
  bookTitle?: string;
  keyPoints: string[];
  terms: string[];
  quote?: string;
  mastered: boolean;
  placeholder: string;
}) {
  // 正面那层：一眼读完的标题、解释、出处。
  const frontBits = (
    <>
      <small>
        {categoryLabel} · {sourceLabel}
      </small>
      <h4>{title.trim() || placeholder}</h4>
      {summary.trim() ? <p>{summary}</p> : null}
      {bookTitle ? <em>{bookTitle}</em> : null}
    </>
  );

  // 背面那层：要点、关联词汇、出处引文。
  const backBits = (
    <>
      {keyPoints.length > 0 ? (
        <section>
          <small>要点</small>
          <ul>
            {keyPoints.slice(0, 4).map((point, index) => (
              <li key={`${index}-${point}`}>{point}</li>
            ))}
          </ul>
        </section>
      ) : null}
      {terms.length > 0 ? (
        <section>
          <small>关联词汇</small>
          <div className="leafia-card-flip__terms">
            {terms.slice(0, 10).map((term, index) => (
              <span key={`${index}-${term}`}>{term}</span>
            ))}
          </div>
        </section>
      ) : null}
      {quote ? <blockquote>{quote}</blockquote> : null}
      {keyPoints.length === 0 && terms.length === 0 && !quote ? (
        <p className="leafia-card-flip__blank">这一面还空着。</p>
      ) : null}
      {mastered ? <span className="leafia-card-flip__stamp">已掌握</span> : null}
    </>
  );

  return {
    front: (
      <div className="leafia-card-flip__face">
        {frontBits}
        <span className="leafia-card-flip__turn" aria-hidden="true">
          <Repeat2 size={12} />
        </span>
      </div>
    ),
    back: <div className="leafia-card-flip__face is-back">{backBits}</div>,
    /** 自建卡不翻：两面摊在同一张纸上，写下什么就看见什么。 */
    still: (
      <div className="leafia-card-flip__face is-still">
        {frontBits}
        {backBits}
      </div>
    ),
  };
}

function KnowledgeDrawer({ onClose }: { onClose: () => void }) {
  const hydrate = useKnowledge((state) => state.hydrate);
  const cards = useKnowledge((state) => state.cards);
  const addManualCard = useKnowledge((state) => state.addManualCard);
  const removeCard = useKnowledge((state) => state.removeCard);
  const setCardMastery = useKnowledge((state) => state.setCardMastery);
  const updateCard = useKnowledge((state) => state.updateCard);
  const [query, setQuery] = useState("");
  const [categoryId, setCategoryId] = useState<string>("all");
  const [composerOpen, setComposerOpen] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [title, setTitle] = useState("");
  const [summary, setSummary] = useState("");
  const [keyPoints, setKeyPoints] = useState("");
  const [terms, setTerms] = useState("");
  const [newCategory, setNewCategory] =
    useState<KnowledgeCategoryId>("linguistics");
  /** 正等着被揉掉的那张知识卡（E3：删除就是把这页纸揉成一团）。 */
  const [pendingRemoval, setPendingRemoval] = useState<KnowledgeCard | null>(
    null,
  );
  /** 封面流正中间那一张卡（按钮行操作它）；筛选一变就落回第一张。 */
  const [activeCardId, setActiveCardId] = useState<string | null>(null);

  useEffect(() => {
    void hydrate();
  }, [hydrate]);

  const filtered = cards.filter((card) => {
    if (categoryId !== "all" && card.categoryId !== categoryId) return false;
    const normalized = query.trim().toLowerCase();
    if (!normalized) return true;
    return `${card.title} ${card.summaryZh} ${card.terms.join(" ")}`
      .toLowerCase()
      .includes(normalized);
  });

  /* 封面流正中间那张：按 id 找回它在筛选后的位置，找不到就落回第一张。 */
  const activeIndex = Math.max(
    0,
    filtered.findIndex((card) => card.id === activeCardId),
  );
  const activeCard: KnowledgeCard | null = filtered[activeIndex] ?? null;
  /* 卡片进封面流：标题 + 解释做正文，类目、来源和掌握状态收进脚下的小字。 */
  const carouselItems = filtered.map((card) => {
    const category = KNOWLEDGE_CATEGORIES.find(
      (item) => item.id === card.categoryId,
    );
    const book = card.bookId ? knowledgeBookById(card.bookId) : undefined;
    return {
      id: card.id,
      title: card.title,
      body: card.summaryZh,
      meta: `${category?.titleZh ?? card.categoryId} · ${
        book?.title ?? (card.source === "manual" ? "自建" : "书本收藏")
      }${card.mastery === "mastered" ? " · 已掌握" : ""}`,
    };
  });

  /** 写入界面那张预览卡跟着正在编辑的这张走：改旧的，类别用旧的，别用新建时的默认值。 */
  const previewCategoryId =
    (editingId ? cards.find((card) => card.id === editingId)?.categoryId : null) ??
    newCategory;

  const resetComposer = () => {
    setEditingId(null);
    setTitle("");
    setSummary("");
    setKeyPoints("");
    setTerms("");
    setComposerOpen(false);
  };

  const save = () => {
    if (!title.trim() || !summary.trim()) return;
    if (editingId) {
      updateCard(editingId, {
        title: title.trim(),
        summaryZh: summary.trim(),
        keyPoints: splitCardLines(keyPoints),
        terms: splitCardLines(terms),
      });
    } else {
      addManualCard({
        categoryId: newCategory,
        title: title.trim(),
        summaryZh: summary.trim(),
        keyPoints: splitCardLines(keyPoints),
        terms: splitCardLines(terms),
      });
    }
    resetComposer();
  };

  const edit = (card: KnowledgeCard) => {
    setEditingId(card.id);
    setTitle(card.title);
    setSummary(card.summaryZh);
    setKeyPoints(card.keyPoints.join("\n"));
    setTerms(card.terms.join(", "));
    setComposerOpen(true);
  };

  return (
    <>
      <div className="leafia-drawer-tools">
        <label>
          <Search size={15} />
          <input
            value={query}
            onChange={(event) => setQuery(event.target.value)}
            placeholder="搜索知识点或词汇…"
          />
        </label>
        <button
          type="button"
          onClick={() => setComposerOpen((value) => !value)}
        >
          <Plus size={15} />
          新建知识卡
        </button>
      </div>

      <div className="leafia-drawer-segments">
        <button
          type="button"
          className={cn(categoryId === "all" && "is-active")}
          onClick={() => setCategoryId("all")}
        >
          全部
        </button>
        {KNOWLEDGE_CATEGORIES.map((category) => (
          <button
            type="button"
            key={category.id}
            className={cn(categoryId === category.id && "is-active")}
            onClick={() => setCategoryId(category.id)}
          >
            {category.titleZh}
          </button>
        ))}
      </div>

      {composerOpen ? (
        <form
          className="leafia-card-composer"
          onSubmit={(event) => {
            event.preventDefault();
            save();
          }}
        >
          <header>
            <strong>{editingId ? "编辑知识卡" : "自建知识卡"}</strong>
            <button type="button" onClick={resetComposer} aria-label="关闭">
              <X size={14} />
            </button>
          </header>
          {/* 写的时候手边就有这张卡（D1）：正面是正在写的标题与解释，
              翻过去是背面将要出现的要点与词汇。 */}
          <FlipCard
            {...knowledgeCardFaces({
              categoryLabel:
                KNOWLEDGE_CATEGORIES.find((item) => item.id === previewCategoryId)
                  ?.titleZh ?? "知识卡",
              sourceLabel: editingId ? "编辑中" : "自建",
              title,
              summary,
              keyPoints: splitCardLines(keyPoints),
              terms: splitCardLines(terms),
              mastered: false,
              placeholder: "标题还没写",
            })}
            width={440}
            height={218}
            radius={10}
            background="#fffdf9"
            color="#3f4254"
            shadow={false}
            tilt={false}
            className="leafia-card-flip-preview"
            ariaLabel="正在写的知识卡，点一下看背面"
          />
          {!editingId ? (
            <select
              value={newCategory}
              onChange={(event) =>
                setNewCategory(event.target.value as KnowledgeCategoryId)
              }
            >
              {KNOWLEDGE_CATEGORIES.map((category) => (
                <option key={category.id} value={category.id}>
                  {category.titleZh} · {category.title}
                </option>
              ))}
            </select>
          ) : null}
          <input
            value={title}
            onChange={(event) => setTitle(event.target.value)}
            placeholder="知识点标题"
          />
          <textarea
            value={summary}
            onChange={(event) => setSummary(event.target.value)}
            placeholder="核心解释"
            rows={4}
          />
          <textarea
            value={keyPoints}
            onChange={(event) => setKeyPoints(event.target.value)}
            placeholder="关键要点，每行一条"
            rows={3}
          />
          <input
            value={terms}
            onChange={(event) => setTerms(event.target.value)}
            placeholder="关联词汇，用逗号分隔"
          />
          <button
            type="submit"
            className="knowledge-primary-button"
            disabled={!title.trim() || !summary.trim()}
          >
            <BookmarkPlus size={15} />
            {editingId ? "保存修改" : "保存知识卡"}
          </button>
        </form>
      ) : null}

      {filtered.length ? (
        /* 卡片列表换成 Prism Carousel：一张张排成弧的封面流，翻到新的一张
           会过一道它自己颜色的棱镜光。按下正中间那张进编辑，底部按钮行
           操作的都是当前正中这张。 */
        <section className="leafia-knowledge-carousel">
          <PrismCarousel
            items={carouselItems}
            activeIndex={activeIndex}
            onActiveChange={(index) =>
              setActiveCardId(filtered[index]?.id ?? null)
            }
            onSelect={(item) => {
              const card = filtered.find((entry) => entry.id === item.id);
              if (card) edit(card);
            }}
          />
          {activeCard ? (
            <footer className="leafia-knowledge-carousel__actions">
              <button type="button" onClick={() => edit(activeCard)}>
                编辑
              </button>
              <button
                type="button"
                onClick={() =>
                  setCardMastery(
                    activeCard.id,
                    activeCard.mastery === "mastered" ? "learning" : "mastered",
                  )
                }
              >
                {activeCard.mastery === "mastered" ? (
                  <>
                    <CheckCircle2 size={13} />
                    已掌握
                  </>
                ) : (
                  "标记掌握"
                )}
              </button>
              <button
                type="button"
                aria-label={`删除 ${activeCard.title}`}
                onClick={() => setPendingRemoval(activeCard)}
              >
                <Trash2 size={13} />
              </button>
            </footer>
          ) : null}
        </section>
      ) : (
        <div className="leafia-drawer-empty">
          <FileText size={20} />
          <strong>还没有知识卡</strong>
          <p>在书本中收藏知识点，或在这里新建一张。</p>
        </div>
      )}

      <DiscardPaper
        spec={
          pendingRemoval
            ? {
                key: `card:${pendingRemoval.id}`,
                kicker: "Discard · 知识收藏",
                title: pendingRemoval.title,
                meta: pendingRemoval.summaryZh,
                seed: pendingRemoval.title.length * 7 + 3,
              }
            : null
        }
        onCancel={() => setPendingRemoval(null)}
        onConfirm={() => {
          if (pendingRemoval) removeCard(pendingRemoval.id);
          setPendingRemoval(null);
        }}
      />
    </>
  );
}

function RecentDrawer({
  events,
  books,
  notes,
  onRemoveNote,
}: {
  events: StudyEvent[];
  books: ReaderBook[];
  notes: DrawerNote[];
  onRemoveNote: (noteId: string) => void;
}) {
  const sortedNotes = drawerNotesIn(notes, "notes").reverse();

  return (
    <>
      {/* C1：这一页改成看走势 —— 近两周的节奏、成色、最近读到的和可翻的记录
          都由 RecentLearningHub 画出来，原来那份「学了什么」的流水账撤下。 */}
      <RecentLearningHub events={events} notes={notes} books={books} />

      {sortedNotes.length ? (
        <section className="leafia-drawer-notes">
          <header>
            <span className="knowledge-eyebrow">Notes</span>
            <h4>便条 · 记录今天</h4>
          </header>
          <ul>
            {sortedNotes.map((note) => (
              <li key={note.id}>
                <span>
                  <strong>{note.title}</strong>
                  <small>{note.meta || "本机便条"}</small>
                </span>
                <button
                  type="button"
                  aria-label={`删除 ${note.title}`}
                  onClick={() => onRemoveNote(note.id)}
                >
                  <Trash2 size={13} />
                </button>
              </li>
            ))}
          </ul>
        </section>
      ) : null}

      {sortedNotes.length ? (
        <section className="leafia-drawer-notes">
          <header>
            <span className="knowledge-eyebrow">Notes</span>
            <h4>便条 · 记录今天</h4>
          </header>
          <ul>
            {sortedNotes.map((note) => (
              <li key={note.id}>
                <span>
                  <strong>{note.title}</strong>
                  <small>{note.meta || "本机便条"}</small>
                </span>
                <button
                  type="button"
                  aria-label={`删除 ${note.title}`}
                  onClick={() => onRemoveNote(note.id)}
                >
                  <Trash2 size={13} />
                </button>
              </li>
            ))}
          </ul>
        </section>
      ) : null}
    </>
  );
}


export function LeafiaDrawerPanel({
  drawerId,
  studyLog,
  books,
  drawerNotes,
  onRemoveNote,
  onOpenWords,
  onClose,
}: {
  drawerId: DrawerId;
  studyLog: StudyEvent[];
  books: ReaderBook[];
  drawerNotes: DrawerNote[];
  onRemoveNote: (noteId: string) => void;
  /** 词汇积累抽屉 → 卡片场那扇浏览器窗口。 */
  onOpenWords: () => void;
  onClose: () => void;
}) {
  const reducedMotion = useReducedMotion();
  const copy = DRAWER_COPY[drawerId];

  return (
    <AnimatePresence>
      <>
        <motion.aside
          className="study-shelf__drawer-panel leafia-functional-drawer"
          aria-label={`${copy.zhLabel}抽屉`}
          initial={{ opacity: 0, y: 72, scale: 0.96 }}
          animate={{ opacity: 1, y: 0, scale: 1 }}
          exit={{ opacity: 0, y: 48, scale: 0.98 }}
          transition={{
            duration: reducedMotion ? 0.01 : 0.4,
            ease: [0.22, 1, 0.36, 1],
          }}
        >
          {/* 抽屉拉开之后不是一张卡片，而是一页「网页」：标签页、地址栏、
              左上角第一颗圆点就是关闭 —— 和单词本、练习册那两扇窗同一副样子。 */}
          <BrowserFrame
            label={copy.zhLabel}
            url={copy.url}
            onClose={onClose}
          >
            <div className="leafia-functional-drawer__body">
              <header className="leafia-functional-drawer__head">
                <span>
                  <small>{copy.label}</small>
                  <strong>{copy.zhLabel}</strong>
                  <em>{copy.description}</em>
                </span>
                <button type="button" onClick={onClose} aria-label="关闭">
                  <X size={15} />
                </button>
              </header>
              {drawerId === "collection" ? (
                <WordDrawer onClose={onClose} onOpenGallery={onOpenWords} />
              ) : drawerId === "materials" ? (
                <KnowledgeDrawer onClose={onClose} />
              ) : (
                <RecentDrawer
                  events={studyLog}
                  books={books}
                  notes={drawerNotes}
                  onRemoveNote={onRemoveNote}
                />
              )}
            </div>
          </BrowserFrame>
        </motion.aside>
      </>
    </AnimatePresence>
  );
}
