export type WordStudyPlan = z.infer<typeof WordStudyPlanSchema>;

export const WordProgressSchema = z.object({
  wordId: z.string().min(1),
  recognitionPassed: z.boolean().default(false),
  spellingPassed: z.boolean().default(false),
  completedPasses: z.number().int().min(0).max(2).default(0),
  errorCount: z.number().int().nonnegative().default(0),
  nextReviewAt: z.string().optional(),
});

export type WordProgress = z.infer<typeof WordProgressSchema>;

